### Functions Are First-Class Citizens

In JavaScript, functions are values — they can be stored in variables, passed as arguments, and returned from other functions. This is the foundation of all the powerful patterns in the language.

#### Three Ways to Create a Function

```javascript
// 1. Function Declaration
// Hoisted — can be called before the declaration in the code
function add(a, b) {
  return a + b;
}

// 2. Function Expression
// Not hoisted — must be declared before calling
const multiply = function(a, b) {
  return a * b;
};

// Named function expression — name visible inside the function (for recursion, stack traces)
const factorial = function fact(n) {
  return n <= 1 ? 1 : n * fact(n - 1); // 'fact' is accessible here
};

// 3. Arrow Function
// Shorter syntax, and critically: does NOT have its own 'this'
const divide = (a, b) => a / b;      // Implicit return when no braces
const square = n => n * n;           // Single param: no parens needed
const greet = () => 'Hello!';        // No params: parens required
const getUser = () => ({ id: 1 });   // Returning object: wrap in parens!
```

#### Parameters: Defaults, Rest, and Destructuring

```javascript
// Default parameters
function createUser(name, role = 'user', active = true) {
  return { name, role, active };
}
createUser('Alice');                    // { name: 'Alice', role: 'user', active: true }
createUser('Bob', 'admin');             // { name: 'Bob', role: 'admin', active: true }
createUser('Charlie', undefined, false); // undefined triggers the default

// Rest parameters — collects remaining args into an array
function sum(first, ...rest) {
  return rest.reduce((total, n) => total + n, first);
}
sum(1, 2, 3, 4, 5); // 15

// Spread in calls — expand an array as arguments
const numbers = [3, 1, 4, 1, 5, 9];
Math.max(...numbers); // 9

// Destructuring in parameters
function displayUser({ name, email, role = 'user' }) {
  console.log(`${name} (${email}) — ${role}`);
}
displayUser({ name: 'Alice', email: 'alice@example.com', role: 'admin' });

// Array destructuring in parameters
function swap([a, b]) {
  return [b, a];
}
swap([1, 2]); // [2, 1]
```

#### `this` — The Most Misunderstood Keyword

`this` refers to the execution context of a function. Its value depends on **how** the function is called, not where it's defined — except for arrow functions, which inherit `this` from the surrounding context.

```javascript
const person = {
  name: 'Alice',

  // Regular method: 'this' is the object the method is called on
  greetRegular: function() {
    console.log(`Hello, I'm ${this.name}`);
  },

  // Arrow function: 'this' is inherited from where the arrow was DEFINED
  // In an object literal, that's the surrounding scope (often global/module)
  greetArrow: () => {
    console.log(`Hello, I'm ${this.name}`); // 'this' is NOT person!
  },

  // Practical use of arrow: callbacks that need 'this'
  greetAfterDelay() {
    setTimeout(() => {
      // 'this' is 'person' because arrow inherits from greetAfterDelay
      console.log(`Hello, I'm ${this.name}`);
    }, 1000);
  },
};

person.greetRegular();   // 'Hello, I\'m Alice'
person.greetArrow();     // 'Hello, I\'m undefined'
person.greetAfterDelay(); // 'Hello, I\'m Alice' (after 1 sec)

// Explicit binding
function greet() {
  return `Hello, ${this.name}`;
}
const alice = { name: 'Alice' };
greet.call(alice);              // 'Hello, Alice' — call with this + args
greet.apply(alice, []);         // same, but args as array
const boundGreet = greet.bind(alice); // Returns new function with this fixed
boundGreet();                   // 'Hello, Alice'
```

#### Pure Functions and Side Effects

```javascript
// Pure: same input always gives same output, no side effects
const add = (a, b) => a + b;
const formatName = (first, last) => `${first} ${last}`;

// Impure: depends on or modifies external state
let total = 0;
const addToTotal = (n) => { total += n; }; // modifies external state
const getTimestamp = () => Date.now();      // different result each time

// Prefer pure functions — they're predictable, testable, and composable
```

---

### Functions That Remember Their Birthplace

A **closure** is created whenever a function is defined inside another function and accesses variables from the outer scope. The inner function "closes over" those variables, keeping them alive even after the outer function has returned.

#### How Closures Work

```javascript
function makeCounter(start = 0) {
  let count = start; // This variable is 'closed over'

  return {
    increment() { return ++count; },
    decrement() { return --count; },
    reset()     { count = start; return count; },
    value()     { return count; },
  };
}

const counter1 = makeCounter(10);
counter1.increment(); // 11
counter1.increment(); // 12
counter1.decrement(); // 11
console.log(counter1.value()); // 11

const counter2 = makeCounter(); // Independent — has its own 'count' variable
counter2.increment();
console.log(counter2.value()); // 1
console.log(counter1.value()); // 11 — unaffected

// count cannot be accessed from outside — true data privacy
// counter1.count is undefined
```

Each call to `makeCounter` creates a **new lexical environment** with its own `count`. The returned object's methods form closures over that specific environment.

#### Practical Pattern: The Module Pattern

Before ES6 modules, closures were used to create private state:

```javascript
const cartModule = (() => {
  // Private state
  const items = [];
  let discount = 0;

  // Private function
  function calculateSubtotal() {
    return items.reduce((sum, item) => sum + item.price * item.qty, 0);
  }

  // Public API
  return {
    addItem(product, qty = 1) {
      const existing = items.find(i => i.id === product.id);
      if (existing) {
        existing.qty += qty;
      } else {
        items.push({ ...product, qty });
      }
    },

    removeItem(id) {
      const index = items.findIndex(i => i.id === id);
      if (index !== -1) items.splice(index, 1);
    },

    setDiscount(pct) {
      discount = Math.min(Math.max(pct, 0), 100);
    },

    getTotal() {
      const subtotal = calculateSubtotal();
      return subtotal * (1 - discount / 100);
    },

    getItemCount() {
      return items.reduce((n, item) => n + item.qty, 0);
    },
  };
})(); // IIFE — immediately invoked
```

#### Memoization with Closures

Closures are perfect for caching expensive computations:

```javascript
function memoize(fn) {
  const cache = new Map(); // Closed over — persists between calls

  return function(...args) {
    const key = JSON.stringify(args);

    if (cache.has(key)) {
      console.log('Cache hit!');
      return cache.get(key);
    }

    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

const expensiveFibonacci = memoize(function fib(n) {
  if (n <= 1) return n;
  return expensiveFibonacci(n - 1) + expensiveFibonacci(n - 2);
});

expensiveFibonacci(40); // Calculated
expensiveFibonacci(40); // Cache hit! Instant.
```

#### The Classic Closure Trap

```javascript
// WRONG: var in a loop — all functions share the same variable
const funcs = [];
for (var i = 0; i < 3; i++) {
  funcs.push(() => console.log(i));
}
funcs[0](); // 3 — i is 3 after the loop ends
funcs[1](); // 3
funcs[2](); // 3

// FIX 1: Use let — each iteration creates a new binding
for (let i = 0; i < 3; i++) {
  funcs.push(() => console.log(i));
}
funcs[0](); // 0
funcs[1](); // 1
funcs[2](); // 2

// FIX 2: Use a factory function (old approach before let)
for (var i = 0; i < 3; i++) {
  funcs.push(((n) => () => console.log(n))(i)); // IIFE captures i by value
}
```

