### The Two Workhorse Data Structures

#### Objects

An object is a collection of key-value pairs. Keys are strings (or Symbols). Values can be anything.

```javascript
// Object literal
const product = {
  id: 'abc-123',
  name: 'Wireless Keyboard',
  price: 89.99,
  inStock: true,
  tags: ['electronics', 'peripherals'],

  // Method shorthand
  getDisplayPrice() {
    return `$${this.price.toFixed(2)}`;
  },

  // Computed property name
  [`sku_${Date.now()}`]: 'generated-key',
};

// Property access
product.name;             // 'Wireless Keyboard'
product['price'];         // 89.99 — use bracket notation for dynamic keys
product['in stock'];      // undefined — bracket notation handles spaces/special chars

// Optional chaining — prevents TypeError on null/undefined
product.specs?.weight;    // undefined (not TypeError)
product.getPrice?.();     // undefined if method doesn't exist
product.images?.[0]?.url; // safe nested access

// Nullish coalescing — fallback only on null/undefined
const price = product.price ?? 0;    // 0 only if null/undefined
const count = product.count || 0;    // 0 for any falsy (including 0 itself — bug!)

// Destructuring
const { name, price, inStock: available } = product; // rename inStock → available
const { id, ...rest } = product;     // id gets its own var, rest gets everything else

// Nested destructuring with defaults
const { specs: { weight = '0g', dimensions = 'N/A' } = {} } = product;

// Spread: create modified copies
const updatedProduct = { ...product, price: 79.99, onSale: true };
const merged = { ...defaultSettings, ...userSettings }; // userSettings wins

// Useful Object methods
Object.keys(product);    // ['id', 'name', 'price', 'inStock', 'tags']
Object.values(product);  // ['abc-123', 'Wireless Keyboard', ...]
Object.entries(product); // [['id', 'abc-123'], ['name', 'Wireless Keyboard'], ...]

// Transform object entries
const doubled = Object.fromEntries(
  Object.entries({ a: 1, b: 2, c: 3 }).map(([k, v]) => [k, v * 2])
);
// { a: 2, b: 4, c: 6 }

Object.freeze(product);  // Shallow immutability — can't add/modify/delete properties
Object.isFrozen(product); // true
```

#### Arrays

Arrays are ordered, zero-indexed lists. They're objects under the hood, but with special behavior.

```javascript
const users = [
  { id: 1, name: 'Alice', age: 30, role: 'admin' },
  { id: 2, name: 'Bob',   age: 25, role: 'user'  },
  { id: 3, name: 'Carol', age: 35, role: 'user'  },
  { id: 4, name: 'Dave',  age: 28, role: 'admin' },
];

// --- The Big Four: map, filter, reduce, find ---

// map: transform every element → new array of same length
const names = users.map(u => u.name);
// ['Alice', 'Bob', 'Carol', 'Dave']

// filter: keep elements that pass a test → new array, possibly shorter
const admins = users.filter(u => u.role === 'admin');
// [{ id: 1, name: 'Alice'... }, { id: 4, name: 'Dave'... }]

// reduce: accumulate to a single value
const totalAge = users.reduce((sum, u) => sum + u.age, 0);
// 118

// Build an object from an array (very common pattern)
const usersById = users.reduce((map, u) => {
  map[u.id] = u;
  return map;
}, {});
// { 1: { id: 1, name: 'Alice'... }, 2: {...}, ... }

// find/findIndex: get first match
const alice = users.find(u => u.name === 'Alice');
const aliceIndex = users.findIndex(u => u.name === 'Alice');

// some/every: existence checks
const hasAdmin = users.some(u => u.role === 'admin');  // true
const allAdult = users.every(u => u.age >= 18);         // true

// --- Sorting (sorts IN PLACE — mutates the array!) ---
const sorted = [...users].sort((a, b) => a.age - b.age);  // ascending age
const byName = [...users].sort((a, b) => a.name.localeCompare(b.name));

// --- Chaining transforms ---
const youngAdminNames = users
  .filter(u => u.role === 'admin')
  .filter(u => u.age < 30)
  .map(u => u.name);
// ['Dave'] — admin AND under 30

// --- flat and flatMap ---
const matrix = [[1, 2], [3, 4], [5, 6]];
matrix.flat();           // [1, 2, 3, 4, 5, 6]
[[1, [2, 3]]].flat(2);   // [1, 2, 3] — depth 2

// flatMap = map then flat(1) — very useful
[1, 2, 3].flatMap(n => [n, n * 2]); // [1, 2, 2, 4, 3, 6]

// --- Checking content ---
users.includes('Alice');  // false — checks reference equality
[1, 2, 3].includes(2);    // true

// --- Destructuring and spread ---
const [first, second, ...rest] = users;
const copy = [...users];
const merged = [...users, ...moreUsers];
```

