### How JavaScript Handles Waiting

JavaScript is **single-threaded** — it can only do one thing at a time. But your apps regularly need to wait for things: network requests, file reads, timers. Blocking the thread while waiting would freeze the entire page.

The solution is the **event loop**: start an operation, register a callback to run when it's done, and keep executing other code in the meantime.

#### The Event Loop (Simplified)

```
Call Stack          Web APIs          Callback Queue
──────────          ────────          ──────────────

main()         →   setTimeout(fn,0)  → [fn] waiting
console.log(1) →   (timer expires)   → [fn] ready
console.log(2)
(stack empty)   ←──────────────────── fn() runs next
```

```javascript
console.log('1');               // Runs immediately

setTimeout(() => {
  console.log('3');             // Runs after stack is empty
}, 0);

Promise.resolve().then(() => {
  console.log('2');             // Microtask — runs before setTimeout callbacks
});

console.log('4');

// Output: 1, 4, 2, 3
// Promises (microtasks) always run before setTimeout (macrotasks)
```

#### Callbacks — The Original Async Pattern

```javascript
// Works, but deeply nested code becomes "callback hell"
fs.readFile('config.json', 'utf8', (err, data) => {
  if (err) { return handleError(err); }

  db.connect(JSON.parse(data).url, (err, conn) => {
    if (err) { return handleError(err); }

    conn.query('SELECT * FROM users', (err, users) => {
      if (err) { return handleError(err); }

      // 3 levels of nesting just to get users...
      processUsers(users);
    });
  });
});
```

#### Promises — Chainable Async

A Promise is an object representing an async operation. It's either **pending**, **fulfilled** (resolved with a value), or **rejected** (failed with a reason).

```javascript
// Creating a Promise
function delay(ms) {
  return new Promise((resolve, reject) => {
    if (ms < 0) reject(new Error('Delay must be positive'));
    else setTimeout(resolve, ms);
  });
}

// Consuming with .then/.catch/.finally
fetchUser(42)
  .then(user => fetchPosts(user.id))  // Chain: each .then receives previous return value
  .then(posts => displayPosts(posts))
  .catch(err => showError(err.message)) // Catches any rejection in the chain
  .finally(() => hideSpinner());        // Always runs

// --- Promise combinators ---

// Promise.all — run in parallel, wait for ALL to complete
// Fails fast: if ANY rejects, the whole thing rejects
const [user, posts, comments] = await Promise.all([
  fetchUser(id),
  fetchPosts(id),
  fetchComments(id),
]);

// Promise.allSettled — run in parallel, wait for ALL to settle (no fail-fast)
const results = await Promise.allSettled([
  fetchUser(1), fetchUser(-1), fetchUser(2)
]);
results.forEach(result => {
  if (result.status === 'fulfilled') console.log(result.value);
  else console.error(result.reason);
});

// Promise.race — first to settle wins (fulfilled OR rejected)
const firstResponse = await Promise.race([
  fetchFromRegion('us'),
  fetchFromRegion('eu'),
]);

// Promise.any — first to FULFILL wins (ignores rejections)
// Rejects only if ALL reject
const firstSuccess = await Promise.any([
  fetchFromPrimary(),
  fetchFromBackup(),
]);
```

#### Async/Await — Synchronous-Looking Async

`async/await` is syntactic sugar over Promises. Every `async` function returns a Promise. `await` pauses execution until the Promise settles.

```javascript
async function loadDashboard(userId) {
  // await pauses this function, but NOT the event loop
  // Other code can run while we wait
  const user = await fetchUser(userId);

  // These don't depend on each other — run in parallel
  const [posts, followers] = await Promise.all([
    fetchPosts(user.id),
    fetchFollowers(user.id),
  ]);

  return { user, posts, followers };
}

// Error handling with try/catch
async function safeLoadDashboard(userId) {
  try {
    return await loadDashboard(userId);
  } catch (err) {
    if (err instanceof NetworkError && err.retryable) {
      await delay(1000);
      return loadDashboard(userId); // Retry once
    }
    throw err; // Re-throw errors you can't handle
  }
}

// GOTCHA: await inside forEach doesn't work!
async function processUsers(users) {
  // BAD: forEach doesn't wait for async callbacks
  users.forEach(async (user) => {
    await sendWelcomeEmail(user.email); // These all start at once, not awaited
  });
  // Function returns before emails are sent!

  // GOOD: for...of respects await (sequential)
  for (const user of users) {
    await sendWelcomeEmail(user.email);
  }

  // GOOD: Promise.all with map (parallel)
  await Promise.all(users.map(user => sendWelcomeEmail(user.email)));
}
```

