### How JavaScript's Inheritance Really Works

JavaScript uses **prototypal inheritance** — objects inherit directly from other objects. When you access a property on an object, JavaScript searches up the **prototype chain** until it finds it or reaches `null`.

#### The Prototype Chain

```javascript
const animal = {
  breathe() { return `${this.name} is breathing`; },
  toString() { return `[Animal: ${this.name}]`; },
};

const dog = Object.create(animal); // dog's [[Prototype]] is animal
dog.name = 'Rex';
dog.bark = function() { return 'Woof!'; };

dog.bark();    // 'Woof!'    — found directly on dog
dog.breathe(); // 'Rex is breathing' — found on animal (prototype)

// Property lookup chain:
// dog → animal → Object.prototype → null

console.log(Object.getPrototypeOf(dog) === animal); // true
console.log('bark' in dog);    // true (own property)
console.log('breathe' in dog); // true (inherited)
console.log(dog.hasOwnProperty('bark'));    // true
console.log(dog.hasOwnProperty('breathe')); // false
```

#### ES6 Classes — Cleaner Prototypal Inheritance

`class` is syntactic sugar over the prototype system. Under the hood, it still creates a prototype chain — but the syntax is much cleaner.

```javascript
class Animal {
  // Private fields — truly private (not on prototype, not enumerable)
  #name;
  #sound;
  #alive = true;

  constructor(name, sound) {
    this.#name = name;
    this.#sound = sound;
  }

  // Getter — access like a property: animal.name
  get name() { return this.#name; }

  // Instance method — on the prototype, shared across all instances
  speak() {
    return `${this.#name} says: ${this.#sound}`;
  }

  describe() {
    return `${this.#name} is ${this.#alive ? 'alive' : 'gone'}`;
  }

  // Static method — on the class itself, not instances
  static create(name, sound) {
    return new Animal(name, sound);
  }

  // Static field
  static kingdom = 'Animalia';
}

class Dog extends Animal {
  #tricks = [];         // Private field with default value
  #breed;               // Private field

  constructor(name, breed) {
    super(name, 'Woof!'); // MUST call super before using 'this'
    this.#breed = breed;
  }

  get breed() { return this.#breed; }

  learn(trick) {
    this.#tricks.push(trick);
    return this; // Return this for method chaining
  }

  perform() {
    if (this.#tricks.length === 0) return `${this.name} hasn't learned any tricks yet`;
    return this.#tricks.map(t => `${this.name} performs: ${t}`).join('\n');
  }

  // Override parent method
  speak() {
    return `${super.speak()} (${this.#breed})`;
  }
}

const rex = new Dog('Rex', 'Labrador');
rex.learn('sit').learn('shake').learn('roll over'); // Method chaining
console.log(rex.speak());    // 'Rex says: Woof! (Labrador)'
console.log(rex.perform());  // 'Rex performs: sit...'
console.log(rex instanceof Dog);    // true
console.log(rex instanceof Animal); // true
console.log(Animal.kingdom);        // 'Animalia'
// console.log(rex.#tricks);        // SyntaxError — truly private
```

#### Mixins — Composing Multiple Behaviors

JavaScript classes only support single inheritance. Mixins let you compose multiple behaviors:

```javascript
// Mixin: a function that takes a class and returns an extended class
const Timestamped = (Base) => class extends Base {
  #createdAt = new Date();
  #updatedAt = new Date();

  get createdAt() { return this.#createdAt; }
  get updatedAt() { return this.#updatedAt; }

  touch() {
    this.#updatedAt = new Date();
    return this;
  }
};

const Serializable = (Base) => class extends Base {
  toJSON() {
    // Get all own enumerable properties
    return Object.fromEntries(
      Object.entries(this).filter(([k]) => !k.startsWith('_'))
    );
  }

  toString() {
    return JSON.stringify(this.toJSON(), null, 2);
  }
};

class User extends Timestamped(Serializable(class {})) {
  constructor(name, email) {
    super();
    this.name = name;
    this.email = email;
  }
}

const user = new User('Alice', 'alice@example.com');
user.touch();
console.log(user.createdAt); // Date object
console.log(user.toJSON());  // { name: 'Alice', email: '...' }
```

