### Communicating with Servers

The `fetch` API is the modern way to make HTTP requests from the browser. It returns a Promise and has a clean, chainable API.

#### Basic GET and POST

```javascript
// GET request
async function getUser(id) {
  const response = await fetch(`/api/users/${id}`);

  // IMPORTANT: fetch only rejects on network failure (no internet, DNS error)
  // HTTP error codes (404, 500) do NOT reject — you must check response.ok
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}: ${response.statusText}`);
  }

  return response.json(); // Parse JSON body
}

// POST request with JSON body
async function createUser(data) {
  const response = await fetch('/api/users', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${getToken()}`,
    },
    body: JSON.stringify(data),
  });

  if (!response.ok) {
    // Try to get error details from response body
    const errorData = await response.json().catch(() => null);
    throw new Error(errorData?.message ?? `HTTP ${response.status}`);
  }

  return response.json();
}

// File upload with FormData
async function uploadFile(file) {
  const formData = new FormData();
  formData.append('file', file);
  formData.append('uploadedBy', getCurrentUserId());

  // DO NOT set Content-Type manually — browser adds the multipart boundary automatically
  const response = await fetch('/api/upload', {
    method: 'POST',
    body: formData,
  });

  return response.json();
}
```

#### Reading Response Data

```javascript
const response = await fetch('/api/data');

// Body can only be read ONCE — after that it's consumed
await response.json();   // Parse as JSON
await response.text();   // As plain text
await response.blob();   // As Blob (binary, e.g. images)
await response.arrayBuffer(); // As ArrayBuffer
await response.formData(); // As FormData

// Useful response metadata
