response.status;   // 200, 404, 500, etc.
response.statusText; // 'OK', 'Not Found', etc.
response.headers.get('Content-Type');
response.url;      // Final URL (after redirects)
response.redirected; // true if a redirect happened
```

#### Request with Timeout

Fetch has no built-in timeout. Use `AbortController`:

```javascript
async function fetchWithTimeout(url, options = {}, timeoutMs = 10_000) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
    });
    return response;
  } catch (err) {
    if (err.name === 'AbortError') {
      throw new Error(`Request timed out after ${timeoutMs}ms`);
    }
    throw err;
  } finally {
    clearTimeout(timeoutId);
  }
}
```

#### Retry with Exponential Backoff

```javascript
async function fetchWithRetry(url, options = {}, maxAttempts = 3) {
  let lastError;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const response = await fetch(url, options);

      // Retry on server errors (5xx) but not client errors (4xx)
      if (!response.ok && response.status >= 500 && attempt < maxAttempts) {
        const delay = Math.min(1000 * 2 ** (attempt - 1), 30_000); // Exponential
        await new Promise(r => setTimeout(r, delay));
        continue;
      }

      return response;
    } catch (err) {
      lastError = err;
      if (attempt < maxAttempts) {
        await new Promise(r => setTimeout(r, 1000 * attempt));
      }
    }
  }

  throw lastError;
}

// Usage
const response = await fetchWithRetry('/api/critical-data', {}, 3);
```

#### Building a Simple API Client

```javascript
class ApiClient {
  #baseUrl;
  #defaultHeaders;

  constructor(baseUrl) {
    this.#baseUrl = baseUrl;
    this.#defaultHeaders = { 'Content-Type': 'application/json' };
  }

  setAuthToken(token) {
    this.#defaultHeaders['Authorization'] = `Bearer ${token}`;
  }

  async request(method, path, { body, headers = {}, ...options } = {}) {
    const response = await fetch(`${this.#baseUrl}${path}`, {
      method,
      headers: { ...this.#defaultHeaders, ...headers },
      body: body ? JSON.stringify(body) : undefined,
      ...options,
    });

    if (!response.ok) {
      const data = await response.json().catch(() => ({}));
      throw Object.assign(new Error(data.message ?? response.statusText), {
        status: response.status,
        data,
      });
    }

    if (response.status === 204) return null; // No content
    return response.json();
  }

  get(path, opts)         { return this.request('GET', path, opts); }
  post(path, body, opts)  { return this.request('POST', path, { body, ...opts }); }
  put(path, body, opts)   { return this.request('PUT', path, { body, ...opts }); }
  patch(path, body, opts) { return this.request('PATCH', path, { body, ...opts }); }
  delete(path, opts)      { return this.request('DELETE', path, opts); }
}

const api = new ApiClient('https://api.myapp.com');
api.setAuthToken(localStorage.getItem('token'));

const user = await api.get('/users/42');
const newPost = await api.post('/posts', { title: 'Hello', body: 'World' });
```

