### Writing Code That Fails Gracefully

Errors are inevitable. A production application must handle them explicitly — not let them crash silently or expose raw stack traces to users.

#### The Error Object and Built-in Types

```javascript
// Built-in error types
new Error('Something went wrong');       // Generic
new TypeError('Expected string, got number'); // Wrong type
new RangeError('Value must be 0-100');   // Out of range
new ReferenceError('x is not defined'); // Invalid reference
new SyntaxError('Unexpected token');     // Parse error
new URIError('Malformed URI');           // URI encoding error

// All errors have:
const err = new Error('Oops');
err.message;  // 'Oops'
err.name;     // 'Error'
err.stack;    // Stack trace string
```

#### Custom Error Classes

```javascript
class AppError extends Error {
  constructor(message, code, statusCode = 500) {
    super(message);
    this.name = this.constructor.name; // 'AppError', 'ValidationError', etc.
    this.code = code;
    this.statusCode = statusCode;
    this.timestamp = new Date().toISOString();

    // Preserve proper stack trace in V8 (Node.js / Chrome)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

class ValidationError extends AppError {
  constructor(message, fields = {}) {
    super(message, 'VALIDATION_ERROR', 422);
    this.fields = fields;
  }
}

class NotFoundError extends AppError {
  constructor(resource, id) {
    super(`${resource} with ID '${id}' not found`, 'NOT_FOUND', 404);
    this.resource = resource;
    this.resourceId = id;
  }
}

class NetworkError extends AppError {
  constructor(message, retryable = true) {
    super(message, 'NETWORK_ERROR', 503);
    this.retryable = retryable;
  }
}

// Throwing and catching specific error types
async function getUser(id) {
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid ID', { id: 'Must be a positive integer' });
  }

  const user = await db.users.findById(id);
  if (!user) throw new NotFoundError('User', id);
  return user;
}

async function handleGetUser(req, res) {
  try {
    const user = await getUser(parseInt(req.params.id));
    res.json(user);
  } catch (err) {
    if (err instanceof ValidationError) {
      return res.status(422).json({ error: err.message, fields: err.fields });
    }
    if (err instanceof NotFoundError) {
      return res.status(404).json({ error: err.message });
    }
    // Unknown error — log and return generic message
    console.error('[ERROR]', err);
    res.status(500).json({ error: 'An unexpected error occurred' });
  }
}
```

#### try/catch/finally Mechanics

```javascript
function example() {
  try {
    // Code that might throw
    const result = riskyOperation();
    return result;
  } catch (err) {
    // Only runs if try block throws
    console.error('Caught:', err.message);
    // If you can handle the error, do so. If not, re-throw.
    if (err instanceof RecoverableError) {
      return defaultValue;
    }
    throw err; // Re-throw errors you can't handle here
  } finally {
    // ALWAYS runs — whether try succeeded, catch ran, or even if throw happened
    cleanup(); // Close files, release locks, hide spinners
  }
}

// Async errors
async function asyncExample() {
  try {
    const data = await fetchData(); // await unwraps rejected promises into throws
    return process(data);
  } catch (err) {
    handleError(err);
  }
}

// Unhandled promise rejections — always handle or catch
// BAD:
fetchData(); // Promise rejection goes unhandled — crashes Node, warning in browser

// GOOD:
await fetchData();
fetchData().catch(console.error);

// Global safety net (last resort)
window.addEventListener('unhandledrejection', (event) => {
  console.error('Unhandled promise rejection:', event.reason);
  event.preventDefault(); // Suppress browser warning
  // Log to error tracking service (Sentry, etc.)
});
```

