### Organising Code Into Files

ES Modules (ESM) are the standard way to split JavaScript into separate files that can import from each other. Every file is its own module — variables and functions are private by default.

#### Named vs Default Exports

```javascript
// utils/math.js

// Named exports — explicitly named, can have many per file
export function add(a, b) { return a + b; }
export function subtract(a, b) { return a - b; }
export const PI = 3.14159;

// You can also export at the bottom (useful to see public API at a glance)
function multiply(a, b) { return a * b; }
function divide(a, b) {
  if (b === 0) throw new Error('Division by zero');
  return a / b;
}
export { multiply, divide };

// Default export — one per file, no name required
export default function formatNumber(n, decimals = 2) {
  return n.toFixed(decimals);
}
```

```javascript
// Importing
import formatNumber from './utils/math.js'; // Default import (name is up to you)
import { add, subtract, PI } from './utils/math.js'; // Named imports
import { multiply as times } from './utils/math.js'; // Rename on import
import * as MathUtils from './utils/math.js'; // Import everything as namespace

MathUtils.add(1, 2);
MathUtils.PI;
MathUtils.default(3.14159); // Access default export via namespace

// Mixed import
import formatNumber, { add, subtract } from './utils/math.js';
```

