### Advanced JavaScript Patterns

#### Functional Programming Principles

```javascript
// --- Pure Functions ---
// Same input → always same output, no side effects
const add = (a, b) => a + b;           // Pure
const double = arr => arr.map(x => x * 2); // Pure — returns new array

let total = 0;
const addToTotal = n => { total += n; }; // Impure — modifies external state

// --- Immutability ---
const user = { name: 'Alice', age: 30, scores: [85, 92] };

// Immutable update patterns
const olderUser = { ...user, age: 31 };                      // Update field
const withNewScore = { ...user, scores: [...user.scores, 99] }; // Add to nested array
const noEmail = Object.fromEntries(
  Object.entries(user).filter(([k]) => k !== 'email')        // Remove field
);

// --- Compose and Pipe ---
const pipe = (...fns) => x => fns.reduce((v, f) => f(v), x);
const compose = (...fns) => x => fns.reduceRight((v, f) => f(v), x);

const processName = pipe(
  str => str.trim(),
  str => str.toLowerCase(),
  str => str.replace(/\s+/g, '-'),
);
processName('  Hello World  '); // 'hello-world'

// --- Currying ---
const curry = fn => {
  const arity = fn.length;
  const curried = (...args) =>
    args.length >= arity ? fn(...args) : (...more) => curried(...args, ...more);
  return curried;
};

const add3 = curry((a, b, c) => a + b + c);
add3(1)(2)(3); // 6
add3(1, 2)(3); // 6
const addTo5 = add3(5); // Partially applied
addTo5(3)(2);  // 10
```

#### Iterators and the Iteration Protocol

An **iterable** is any object that has a `[Symbol.iterator]` method returning an **iterator** (an object with a `next()` method that returns `{ value, done }`).

```javascript
// Arrays, strings, Maps, Sets are built-in iterables
for (const char of 'hello') console.log(char); // h, e, l, l, o
for (const [key, val] of new Map([[1, 'a'], [2, 'b']])) {}

// Implementing a custom iterable — a range
function range(start, end, step = 1) {
  return {
    [Symbol.iterator]() {
      let current = start;
      return {
        next() {
          if (current < end) {
            const value = current;
            current += step;
            return { value, done: false };
          }
          return { value: undefined, done: true };
        }
      };
    }
  };
}

for (const n of range(0, 10, 2)) {
  console.log(n); // 0, 2, 4, 6, 8
}

const nums = [...range(1, 6)]; // [1, 2, 3, 4, 5]
```

#### Generators — Pausable Functions

A generator function can `yield` values one at a time. Execution pauses at each `yield` and resumes on the next call to `.next()`.

```javascript
// Generator function (note the * )
function* counter(start = 0) {
  while (true) {
    const reset = yield start++; // yield pauses, returns value to caller
    if (reset) start = 0;        // caller can send values in via next(value)
  }
}

const gen = counter(1);
gen.next().value;       // 1
gen.next().value;       // 2
gen.next().value;       // 3
gen.next(true).value;   // 0 (reset)
gen.next().value;       // 1

// Generator as a clean infinite sequence
function* fibonacci() {
  let [a, b] = [0, 1];
  while (true) {
    yield a;
    [a, b] = [b, a + b];
  }
}

function take(n, iterable) {
  const result = [];
  for (const value of iterable) {
    result.push(value);
    if (result.length === n) break;
  }
  return result;
}

take(8, fibonacci()); // [0, 1, 1, 2, 3, 5, 8, 13]
```

#### Proxy — Intercept Object Operations

`Proxy` lets you intercept and customise operations on objects (property access, assignment, function calls).

```javascript
// Validation proxy
function createValidatedUser(data) {
  const validators = {
    name: v => typeof v === 'string' && v.length >= 2,
    age:  v => Number.isInteger(v) && v >= 0 && v <= 150,
    email: v => typeof v === 'string' && v.includes('@'),
  };

  return new Proxy(data, {
    set(target, prop, value) {
      if (prop in validators && !validators[prop](value)) {
        throw new TypeError(`Invalid value for '${prop}': ${value}`);
      }
      target[prop] = value;
      return true; // Required: return true to indicate success
    }
  });
}

const user = createValidatedUser({});
user.name = 'Alice'; // OK
user.age = 30;       // OK
user.name = 'A';     // TypeError: Invalid value for 'name': A
```

